// Images are assembled independently from REL_18_6 brin_page.h, bufpage.h,
// itemid.h, brin_tuple.h and tupmacs.h (amd64, little endian, BLCKSZ 8192).
// They are not generated by engine code or from the descriptor table's rows.
func BRINImage(tag uint16) []byte {
	p := make([]byte, 8192)
	binary.LittleEndian.PutUint16(p[12:], 24)
	binary.LittleEndian.PutUint16(p[14:], 8184)
	binary.LittleEndian.PutUint16(p[16:], 8184)
	binary.LittleEndian.PutUint16(p[18:], 0x2004)
	binary.LittleEndian.PutUint16(p[8190:], tag)
	return p
}

func BRINMeta() []byte {
	p := BRINImage(0xf091)
	for i, v := range []uint32{0xa8109cfa, 1, 128, 1} {
		binary.LittleEndian.PutUint32(p[24+i*4:], v)
	}
	return p
}

func BRINBoth(t *testing.T, p *Pair, b Backend, c *sql.Conn, s Step) {
	t.Helper()
	RunStep(t, p.Ctx, c, b.Recorder, s)
	RunStep(t, p.Ctx, c, b.Recorder, Prepared(s))
}

// Scan types follow the public adapters, not the values in the first row.
// pq v1.12.3 rows.go fieldDesc.Type reports TID as interface{} and INT4 as
// int32; native reports immutable TID text and its common int64 integer carrier.
// Function expressions/sources have unknown native nullability; stored view
// columns are declared nullable. pq honestly reports unknown nullability.
func BRINMetadata(s Step, pg, view bool) Step {
	names, types := s.Columns, s.Types
	s.CheckMetadata = func(t *testing.T, rows *sql.Rows) {
		t.Helper()
		columns, err := rows.ColumnTypes()
		if err != nil || len(columns) != len(names) {
			t.Fatal("BRIN metadata width", columns, err)
		}
		for i, column := range columns {
			if column.Name() != names[i] || column.DatabaseTypeName() != types[i] {
				t.Fatal("BRIN column declaration", i, column.Name(), column.DatabaseTypeName(), names[i], types[i])
			}
			var scan reflect.Type
			switch types[i] {
			case "TEXT":
				scan = reflect.TypeFor[string]()
			case "BOOL":
				scan = reflect.TypeFor[bool]()
			case "INT4":
				scan = reflect.TypeFor[int64]()
				if pg {
					scan = reflect.TypeFor[int32]()
				}
			case "INT8":
				scan = reflect.TypeFor[int64]()
			case "TID", "RECORD":
				scan = reflect.TypeFor[string]()
				if pg {
					scan = reflect.TypeFor[any]()
				}
			default:
				t.Fatal("missing independent BRIN scan expectation", types[i])
			}
			if column.ScanType() != scan {
				t.Fatal("BRIN scan type", i, column.ScanType(), scan)
			}
			nullable, known := column.Nullable()
			want := view && !pg
			if nullable != want || known != want {
				t.Fatal("BRIN nullable declaration", i, nullable, known, want, want)
			}
		}
	}
	return s
}

// Independently assembled REL_18_6 bufpage/itemid/itup/nbtree images.
func BTTID(p []byte, block uint32, offset uint16) {
	binary.LittleEndian.PutUint16(p, uint16(block>>16))
	binary.LittleEndian.PutUint16(p[2:], uint16(block))
	binary.LittleEndian.PutUint16(p[4:], offset)
}

func BTTuple(block uint32, offset, info uint16, payload ...byte) []byte {
	p := make([]byte, 8+len(payload))
	BTTID(p, block, offset)
	binary.LittleEndian.PutUint16(p[6:], info)
	copy(p[8:], payload)
	return p
}

func BTPage(flags uint16, level, next uint32, tuples ...[]byte) []byte {
	p := make([]byte, 8192)
	upper := 8176
	binary.LittleEndian.PutUint16(p[12:], uint16(24+4*len(tuples)))
	binary.LittleEndian.PutUint16(p[16:], 8176)
	binary.LittleEndian.PutUint16(p[18:], 0x2004)
	binary.LittleEndian.PutUint32(p[8180:], next)
	binary.LittleEndian.PutUint32(p[8184:], level)
	binary.LittleEndian.PutUint16(p[8188:], flags)
	for i, tuple := range tuples {
		upper = (upper - len(tuple)) & -8
		copy(p[upper:], tuple)
		binary.LittleEndian.PutUint32(p[24+4*i:], uint32(upper)|1<<15|uint32(len(tuple))<<17)
	}
	binary.LittleEndian.PutUint16(p[14:], uint16(upper))
	return p
}

var BTKey = []byte{42, 0, 0, 0, 0, 0, 0, 0}

func BTOrdinary() []byte {
	return BTPage(1, 0, 0, BTTuple(65538, 513, 16, 249, 255, 255, 255, 0, 0, 0, 0))
}

func BTPosting() []byte {
	p := BTTuple(16, 8194, 0x2020, make([]byte, 24)...)
	copy(p[8:], BTKey)
	BTTID(p[16:], 1, 6)
	BTTID(p[22:], 65538, 513)
	copy(p[28:], []byte{9, 8, 7, 6})
	return BTPage(1, 0, 0, p)
}

