func BTMetadata(s Step, pg, view bool) Step {
	names, types := s.Columns, s.Types
	s.CheckMetadata = func(t *testing.T, r *sql.Rows) {
		t.Helper()
		columns, err := r.ColumnTypes()
		if err != nil || len(columns) != len(names) {
			t.Fatal(columns, err)
		}
		for i, c := range columns {
			if c.Name() != names[i] || c.DatabaseTypeName() != types[i] {
				t.Fatal(i, c.Name(), c.DatabaseTypeName())
			}
			var scan reflect.Type
			switch types[i] {
			case "INT2":
				scan = reflect.TypeFor[int64]()
				if pg {
					scan = reflect.TypeFor[int16]()
				}
			case "BOOL":
				scan = reflect.TypeFor[bool]()
			case "TEXT":
				scan = reflect.TypeFor[string]()
			case "TID", "_TID", "RECORD":
				scan = reflect.TypeFor[string]()
				if pg {
					scan = reflect.TypeFor[any]()
				}
			default:
				t.Fatal("unmapped metadata", types[i])
			}
			if c.ScanType() != scan {
				t.Fatal(i, c.ScanType(), scan)
			}
			n, k := c.Nullable()
			want := view && !pg
			if n != want || k != want {
				t.Fatal(i, n, k, want)
			}
			length, known := c.Length()
			if types[i] == "TEXT" {
				if length != math.MaxInt64 || !known {
					t.Fatal(i, length, known)
				}
			} else if length != 0 || known {
				t.Fatal(i, length, known)
			}
			precision, scale, known := c.DecimalSize()
			if precision != 0 || scale != 0 || known {
				t.Fatal(i, precision, scale, known)
			}
		}
	}
	return s
}

func BTDeclaration(name, schema, owner string) Step {
	s := Select("SELECT p.proname::text AS name,n.nspname::text AS schema,r.rolname::text AS owner,p.pronargs::integer AS nargs,p.prorettype::bigint AS result,p.proargtypes::text AS args,p.proallargtypes::text AS allargs,p.proargmodes::text AS modes,p.proargnames::text AS names,p.proretset AS sets,p.proisstrict AS strict,p.provolatile::text AS volatility,p.proparallel::text AS parallel,p.prosrc AS source FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner JOIN pg_depend d ON d.objid=p.oid JOIN pg_extension e ON e.oid=d.refobjid WHERE d.classid=1255 AND d.refclassid=3079 AND d.deptype='e' AND e.extname='pageinspect' AND p.proname='"+name+"' AND p.proargtypes::text='17'", []string{"name", "schema", "owner", "nargs", "result", "args", "allargs", "modes", "names", "sets", "strict", "volatility", "parallel", "source"}, []string{"TEXT", "TEXT", "TEXT", "INT4", "INT8", "TEXT", "TEXT", "TEXT", "TEXT", "BOOL", "BOOL", "TEXT", "TEXT", "TEXT"}, [][]any{{name, schema, owner, int64(1), int64(2249), "17", "{17,21,27,21,16,16,25,16,27,1010}", "{i,o,o,o,o,o,o,o,o,o}", "{page,itemoffset,ctid,itemlen,nulls,vars,data,dead,htid,tids}", true, true, "v", "s", "bt_page_items_bytea"}})
	s.Bag = true
	return s
}

// Independent REL_18_6 little-endian bufpage/FSM images, not engine pages.
const FSMSparseText = "0: 255\n1: 128\n4094: 127\n4095: 1\n8163: 254\nfp_next_slot: 16909060\n"

func FSMPage(pointer uint32) []byte {
	p := make([]byte, 8192)
	binary.LittleEndian.PutUint16(p[12:], 24)
	binary.LittleEndian.PutUint16(p[14:], 8192)
	binary.LittleEndian.PutUint16(p[16:], 8192)
	binary.LittleEndian.PutUint16(p[18:], 0x2004)
	binary.LittleEndian.PutUint32(p[24:], pointer)
	return p
}

func FSMSparse() []byte {
	p := FSMPage(0x01020304)
	for i, v := range map[int]byte{0: 255, 1: 128, 4094: 127, 4095: 1, 8163: 254} {
		p[28+i] = v
	}
	return p
}

