func GINNullRows(i int) [][]any { return [][]any{make([]any, len(GINNames[i]))} }

func GINCheckColumns(t *testing.T, columns []*sql.ColumnType, names, types []string, pg, view bool) {
	t.Helper()
	if len(columns) != len(names) {
		t.Fatal("column count", len(columns), names)
	}
	for i, c := range columns {
		if c.Name() != names[i] || c.DatabaseTypeName() != types[i] {
			t.Fatal(i, c.Name(), c.DatabaseTypeName(), names[i], types[i])
		}
		var scan reflect.Type
		switch types[i] {
		case "INT8":
			scan = reflect.TypeFor[int64]()
		case "INT4":
			scan = reflect.TypeFor[int64]()
			if pg {
				scan = reflect.TypeFor[int32]()
			}
		case "INT2":
			scan = reflect.TypeFor[int64]()
			if pg {
				scan = reflect.TypeFor[int16]()
			}
		case "TID", "_TID", "_TEXT", "RECORD":
			scan = reflect.TypeFor[string]()
			if pg {
				scan = reflect.TypeFor[any]()
			}
		default:
			t.Fatal("unmapped GIN type", types[i])
		}
		if c.ScanType() != scan {
			t.Fatal(i, "ScanType", c.ScanType(), scan)
		}
		n, k := c.Nullable()
		want := view && !pg
		if n != want || k != want {
			t.Fatal(i, "Nullable", n, k, "want", want, want)
		}
		length, known := c.Length()
		if length != 0 || known {
			t.Fatal(i, "Length", length, known)
		}
		precision, scale, known := c.DecimalSize()
		if precision != 0 || scale != 0 || known {
			t.Fatal(i, "DecimalSize", precision, scale, known)
		}
	}
}

func GINMetadata(s Step, pg, view bool) Step {
	s.CheckMetadata = func(t *testing.T, r *sql.Rows) {
		columns, err := r.ColumnTypes()
		if err != nil {
			t.Fatal(err)
		}
		GINCheckColumns(t, columns, s.Columns, s.Types, pg, view)
	}
	return s
}

